type ColorProps = CommonProps & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
};

function Color({
  label,
  value,
  defaultValue = "",
  onValueChange,
  disabled,
  className,
  name,
}: ColorProps) {
  const [local, setLocal] = React.useState(defaultValue);
  const [draft, setDraft] = React.useState(value ?? defaultValue);
  const current = value ?? local;
  const [previous, setPrevious] = React.useState(current);
  if (previous !== current) {
    setPrevious(current);
    setDraft(current);
  }
  const valid = /^#[\da-fA-F]{6}$/.test(current);
  const change = (next: string) => {
    setLocal(next);
    setDraft(next);
    onValueChange?.(next);
  };
  // The hex input is the Field control (the label targets it); the native color
  // input has no Base UI part, so it carries the form name and always holds a
  // valid hex, which replaces the old hidden input.
  return (
    <FieldPrimitive.Root
      data-slot="control-color"
      disabled={disabled}
      className={cn(rowClass, className)}
    >
      <FieldPrimitive.Label className={labelClass}>{label}</FieldPrimitive.Label>
      <InputPrimitive
        aria-label={`${label} hex value`}
        // Field.Label would name the input "Fill"; keep the hex-specific name.
        aria-labelledby={undefined}
        value={draft}
        onValueChange={(next) => {
          setDraft(next);
          if (/^#[\da-fA-F]{6}$/.test(next)) change(next);
        }}
        className={cn(valueClass, monoClass, "w-20 bg-transparent")}
      />
      <span
        className="relative size-5 shrink-0 overflow-hidden rounded-md border surface-knob bg-(--control-color)!"
        style={{ "--control-color": valid ? current : "transparent" } as React.CSSProperties}
      >
        <input
          aria-label={`Pick ${label}`}
          type="color"
          name={name}
          disabled={disabled}
          value={valid ? current : ""}
          onChange={(event) => change(event.target.value)}
          className="absolute inset-0 size-full cursor-pointer opacity-0"
        />
      </span>
    </FieldPrimitive.Root>
  );
}

type ImageProps = CommonProps & {
  src?: string;
  options?: readonly (Option & { src: string })[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onFileChange?: (file: File | null) => void;
  accept?: string;
  name?: string;
};

function Image({
  label,
  src,
  options,
  value,
  defaultValue,
  onValueChange,
  onFileChange,
  accept = "image/*",
  disabled,
  className,
  name,
}: ImageProps) {
  const ref = React.useRef<HTMLInputElement>(null);
  const [selectedValue, setSelectedValue] = React.useState(defaultValue ?? options?.[0]?.value);
  const selected = options?.find((option) => option.value === (value ?? selectedValue));
  const preview = selected?.src ?? src;
  return (
    <div data-slot="control-image" className={cn(rowClass, className)}>
      <span className={labelClass}>{label}</span>
      {options?.length ? (
        <SelectPrimitive.Root
          items={options}
          value={value ?? selectedValue}
          onValueChange={(next) => {
            if (next !== null) {
              setSelectedValue(next);
              onValueChange?.(next);
            }
          }}
          disabled={disabled}
          name={name}
        >
          <SelectPrimitive.Trigger
            aria-label={label}
            className="group group/control-select ms-auto flex min-w-0 items-center gap-related rounded-sm text-control text-muted-foreground outline-none hover:text-foreground"
          >
            {preview ? (
              <img alt="" src={preview} className="size-6 rounded-sm object-cover" />
            ) : null}
            <SelectPrimitive.Value className="max-w-24 truncate" />
            <SelectPrimitive.Icon>
              <RotatingChevron className="size-3.5" />
            </SelectPrimitive.Icon>
          </SelectPrimitive.Trigger>
          <OptionsPopup className="flex max-h-(--available-height) min-w-(--anchor-width) flex-col overflow-hidden rounded-lg surface-overlay outline-none">
            {options.map((option) => (
              <SelectPrimitive.Item
                key={option.value}
                value={option.value}
                className="flex cursor-default items-center gap-related rounded-md px-2 py-1.5 text-control outline-none data-highlighted:bg-accent data-highlighted:text-accent-foreground"
              >
                <img alt="" src={option.src} className="size-6 rounded-sm object-cover" />
                <SelectPrimitive.ItemText>{option.label}</SelectPrimitive.ItemText>
                <SelectPrimitive.ItemIndicator className="ms-auto">
                  <HugeiconsIcon icon={CheckIcon} className="size-3.5" />
                </SelectPrimitive.ItemIndicator>
              </SelectPrimitive.Item>
            ))}
          </OptionsPopup>
        </SelectPrimitive.Root>
      ) : null}
      {onFileChange || !options?.length ? (
        <ButtonPrimitive
          disabled={disabled}
          aria-label={`Upload ${label}`}
          onClick={() => ref.current?.click()}
          data-no-options={!options?.length ? "" : undefined}
          className={cn(
            "flex min-w-0 items-center gap-related rounded-sm text-control text-muted-foreground hover:text-foreground data-no-options:ms-auto",
          )}
        >
          {!options?.length && preview ? (
            <img alt="" src={preview} className="size-6 rounded-sm object-cover" />
          ) : (
            <HugeiconsIcon icon={ImagePlusIcon} className="size-4" />
          )}
          {!options?.length ? <span>{preview ? "Change" : "Choose image"}</span> : null}
        </ButtonPrimitive>
      ) : null}
      <input
        ref={ref}
        type="file"
        name={options?.length ? undefined : name}
        accept={accept}
        disabled={disabled}
        tabIndex={-1}
        className="sr-only"
        onChange={(event) => onFileChange?.(event.target.files?.[0] ?? null)}
      />
    </div>
  );
}

type PadValue = { x: number; y: number };
type PadProps = CommonProps & {
  value?: PadValue;
  defaultValue?: PadValue;
  onValueChange?: (value: PadValue) => void;
  min?: number;
  max?: number;
  step?: number;
};

function Pad({
  label,
  value,
  defaultValue = { x: 0, y: 0 },
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  disabled,
  className,
}: PadProps) {
  const [local, setLocal] = React.useState(defaultValue);
  const current = value ?? local;
  const ref = React.useRef<HTMLDivElement>(null);
  const span = max > min ? max - min : 1;
  const safeStep = step > 0 ? step : 1;
  const change = (next: PadValue) => {
    setLocal(next);
    onValueChange?.(next);
  };
  const fromPointer = (event: React.PointerEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    const snap = (fraction: number) =>
      Math.max(min, Math.min(max, min + Math.round((span * fraction) / safeStep) * safeStep));
    change({
      x: snap((event.clientX - rect.left) / rect.width),
      y: snap(1 - (event.clientY - rect.top) / rect.height),
    });
  };
  return (
    <div data-slot="control-pad" className={cn("rounded-lg border surface-control p-3", className)}>
      <div className={cn(labelClass, "mb-2")}>{label}</div>
      <div
        ref={ref}
        aria-hidden="true"
        className="relative h-24 w-full touch-none rounded-md surface-well"
        onPointerDown={(event) => {
          if (disabled) return;
          event.currentTarget.setPointerCapture(event.pointerId);
          fromPointer(event);
        }}
        onPointerMove={(event) => {
          if (event.currentTarget.hasPointerCapture(event.pointerId)) fromPointer(event);
        }}
      >
        <span
          className="left-(--control-point-x) top-(--control-point-y) pointer-events-none absolute size-3 -translate-x-1/2 -translate-y-1/2 rounded-full border surface-knob bg-selection"
          style={
            {
              "--control-point-x": `${((current.x - min) / span) * 100}%`,
              "--control-point-y": `${100 - ((current.y - min) / span) * 100}%`,
            } as React.CSSProperties
          }
        />
      </div>
      <div className="mt-1.5 grid grid-cols-2 gap-1.5">
        <ControlNumber
          label="X"
          value={current.x}
          onValueChange={(x) => change({ ...current, x })}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
        />
        <ControlNumber
          label="Y"
          value={current.y}
          onValueChange={(y) => change({ ...current, y })}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
        />
      </div>
    </div>
  );
}

type SpringValue =
  | { type: "spring"; visualDuration: number; bounce: number }
  | { type: "spring"; stiffness: number; damping: number; mass: number };
type EasingValue = { type: "easing"; duration: number; ease: [number, number, number, number] };
type TransitionValue = SpringValue | EasingValue;
type SpringProps = CommonProps & {
  value?: SpringValue;
  defaultValue?: SpringValue;
  onValueChange?: (value: SpringValue) => void;
};
type TransitionProps = CommonProps & {
  value?: TransitionValue;
  defaultValue?: TransitionValue;
  onValueChange?: (value: TransitionValue) => void;
};

const defaultTimeSpring: SpringValue = { type: "spring", visualDuration: 0.3, bounce: 0.2 };
const defaultPhysicsSpring: SpringValue = { type: "spring", stiffness: 200, damping: 25, mass: 1 };
const defaultEasing: EasingValue = { type: "easing", duration: 0.3, ease: [0.25, 0.1, 0.25, 1] };

function springIsTime(
  value: SpringValue,
): value is Extract<SpringValue, { visualDuration: number }> {
  return "visualDuration" in value;
}

function SpringCurve({ value }: { value: SpringValue }) {
  const time = springIsTime(value);
  const stiffness = time ? 200 : value.stiffness;
  const mass = time ? 1 : value.mass;
  const damping = time
    ? 2 * Math.sqrt(stiffness * mass) * (1 - value.bounce * 0.75)
    : value.damping;
  const omega = Math.sqrt(stiffness / mass);
  const ratio = damping / (2 * Math.sqrt(stiffness * mass));
  const duration = time ? Math.max(0.1, value.visualDuration) * 2 : 1.5;
  const points = Array.from({ length: 65 }, (_, index) => {
    const t = (index / 64) * duration;
    const response =
      ratio < 1
        ? 1 -
          Math.exp(-ratio * omega * t) *
            (Math.cos(omega * Math.sqrt(1 - ratio * ratio) * t) +
              (ratio / Math.sqrt(1 - ratio * ratio)) *
                Math.sin(omega * Math.sqrt(1 - ratio * ratio) * t))
        : 1 - (1 + omega * t) * Math.exp(-omega * t);
    return `${index === 0 ? "M" : "L"}${(index / 64) * 100} ${80 - response * 60}`;
  });
  return <CurveFrame path={points.join(" ")} />;
}

function CurveFrame({ path }: { path: string }) {
  return (
    <div aria-hidden="true" className="h-24 overflow-hidden rounded-lg border surface-control">
      <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="size-full text-foreground">
        <path
          d="M0 20 H100 M0 80 H100"
          stroke="currentColor"
          strokeOpacity="0.12"
          strokeWidth="0.5"
          strokeDasharray="2 2"
        />
        <path
          d={path}
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
    </div>
  );
}

function Spring({
  label,
  value,
  defaultValue = defaultTimeSpring,
  onValueChange,
  disabled,
  className,
}: SpringProps) {
  const [local, setLocal] = React.useState<SpringValue>(defaultValue);
  const current = value ?? local;
  const cache = React.useRef({ time: defaultTimeSpring, physics: defaultPhysicsSpring });
  React.useLayoutEffect(() => {
    cache.current[springIsTime(current) ? "time" : "physics"] = current;
  }, [current]);
  const change = (next: SpringValue) => {
    setLocal(next);
    onValueChange?.(next);
  };
  return (
    <Section title={label} className={className}>
      <SpringCurve value={current} />
      <Segmented
        label="Type"
        value={springIsTime(current) ? "time" : "physics"}
        options={[
          { value: "time", label: "Time" },
          { value: "physics", label: "Physics" },
        ]}
        onValueChange={(mode) => change(cache.current[mode === "time" ? "time" : "physics"])}
        disabled={disabled}
      />
      {springIsTime(current) ? (
        <>
          <ControlNumber
            label="Duration"
            value={current.visualDuration}
            onValueChange={(visualDuration) => change({ ...current, visualDuration })}
            min={0.1}
            max={2}
            step={0.01}
            formatValue={(v) => `${v.toFixed(2)} s`}
            disabled={disabled}
          />
          <ControlNumber
            label="Bounce"
            value={current.bounce}
            onValueChange={(bounce) => change({ ...current, bounce })}
            min={0}
            max={1}
            step={0.01}
            disabled={disabled}
          />
        </>
      ) : (
        <>
          <ControlNumber
            label="Stiffness"
            value={current.stiffness}
            onValueChange={(stiffness) => change({ ...current, stiffness })}
            min={1}
            max={1000}
            step={1}
            disabled={disabled}
          />
          <ControlNumber
            label="Damping"
            value={current.damping}
            onValueChange={(damping) => change({ ...current, damping })}
            min={1}
            max={100}
            step={1}
            disabled={disabled}
          />
          <ControlNumber
            label="Mass"
            value={current.mass}
            onValueChange={(mass) => change({ ...current, mass })}
            min={0.1}
            max={10}
            step={0.1}
            disabled={disabled}
          />
        </>
      )}
    </Section>
  );
}

function Transition({
  label,
  value,
  defaultValue = defaultEasing,
  onValueChange,
  disabled,
  className,
}: TransitionProps) {
  const [local, setLocal] = React.useState<TransitionValue>(defaultValue);
  const current = value ?? local;
  const cache = React.useRef<{ easing: EasingValue; time: SpringValue; physics: SpringValue }>({
    easing: defaultEasing,
    time: defaultTimeSpring,
    physics: defaultPhysicsSpring,
  });
  const mode = current.type === "easing" ? "easing" : springIsTime(current) ? "time" : "physics";
  React.useLayoutEffect(() => {
    if (current.type === "easing") cache.current.easing = current;
    else if (springIsTime(current)) cache.current.time = current;
    else cache.current.physics = current;
  }, [current]);
  const change = (next: TransitionValue) => {
    setLocal(next);
    onValueChange?.(next);
  };
  const updateEase = (index: number, next: number) => {
    if (current.type !== "easing") return;
    const ease = [...current.ease] as [number, number, number, number];
    ease[index] = next;
    change({ ...current, ease });
  };
  return (
    <Section title={label} className={className}>
      {current.type === "easing" ? (
        <CurveFrame
          path={`M0 80 C${current.ease[0] * 100} ${80 - current.ease[1] * 60}, ${current.ease[2] * 100} ${80 - current.ease[3] * 60}, 100 20`}
        />
      ) : (
        <SpringCurve value={current} />
      )}
      <Segmented
        label="Type"
        value={mode}
        options={[
          { value: "easing", label: "Easing" },
          { value: "time", label: "Time" },
          { value: "physics", label: "Physics" },
        ]}
        onValueChange={(next) => change(cache.current[next as keyof typeof cache.current])}
        disabled={disabled}
      />
      {current.type === "easing" ? (
        <>
          <ControlNumber
            label="Duration"
            value={current.duration}
            onValueChange={(duration) => change({ ...current, duration })}
            min={0.1}
            max={2}
            step={0.01}
            formatValue={(v) => `${v.toFixed(2)} s`}
            disabled={disabled}
          />
          <div className="grid grid-cols-2 gap-1.5">
            {(["X1", "Y1", "X2", "Y2"] as const).map((axis, index) => (
              <ControlNumber
                key={axis}
                label={axis}
                value={current.ease[index]}
                onValueChange={(next) => updateEase(index, next)}
                min={index % 2 === 0 ? 0 : -1}
                max={index % 2 === 0 ? 1 : 2}
                step={0.01}
                disabled={disabled}
              />
            ))}
          </div>
        </>
      ) : springIsTime(current) ? (
        <>
          <ControlNumber
            label="Duration"
            value={current.visualDuration}
            onValueChange={(visualDuration) => change({ ...current, visualDuration })}
            min={0.1}
            max={2}
            step={0.01}
            disabled={disabled}
          />
          <ControlNumber
            label="Bounce"
            value={current.bounce}
            onValueChange={(bounce) => change({ ...current, bounce })}
            min={0}
            max={1}
            step={0.01}
            disabled={disabled}
          />
        </>
      ) : (
        <>
          <ControlNumber
            label="Stiffness"
            value={current.stiffness}
            onValueChange={(stiffness) => change({ ...current, stiffness })}
            min={1}
            max={1000}
            step={1}
            disabled={disabled}
          />
          <ControlNumber
            label="Damping"
            value={current.damping}
            onValueChange={(damping) => change({ ...current, damping })}
            min={1}
            max={100}
            step={1}
            disabled={disabled}
          />
          <ControlNumber
            label="Mass"
            value={current.mass}
            onValueChange={(mass) => change({ ...current, mass })}
            min={0.1}
            max={10}
            step={0.1}
            disabled={disabled}
          />
        </>
      )}
    </Section>
  );
}

type ActionProps = CommonProps & Omit<React.ComponentProps<"button">, "children" | "disabled">;
function Action({ label, disabled, className, ...props }: ActionProps) {
  return (
    <ButtonPrimitive
      data-slot="control-action"
      disabled={disabled}
      className={cn(rowClass, "justify-center font-medium outline-none", className)}
      {...props}
    >
      {label}
    </ButtonPrimitive>
  );
}

type SectionProps = {
  title: string;
  children: React.ReactNode;
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
};
function Section({
  title,
  children,
  defaultOpen = true,
  open,
  onOpenChange,
  className,
}: SectionProps) {
  return (
    <Collapsible
      data-slot="control-section"
      defaultOpen={defaultOpen}
      open={open}
      onOpenChange={onOpenChange}
      className={cn("w-full min-w-0", className)}
    >
      <Separator className="mb-2" />
      <CollapsibleTrigger className="group group/section flex w-full items-center justify-between text-start text-control font-medium text-muted-foreground outline-none hover:text-foreground">
        {title}
        <RotatingChevron scope="collapsible" className="size-4" />
      </CollapsibleTrigger>
      <CollapsibleContent className="data-open:overflow-visible">
        <Group className="py-2">{children}</Group>
      </CollapsibleContent>
    </Collapsible>
  );
}

const Control = {
  Group,
  Row,
  Number: ControlNumber,
  Text,
  Textarea,
  Boolean,
  Segmented,
  Select,
  Color,
  Image,
  Pad,
  Spring,
  Transition,
  Action,
  Section,
};

export { Control };
export type {
  NumberProps,
  TextProps,
  TextareaProps,
  BooleanProps,
  ChoiceProps,
  ColorProps,
  ImageProps,
  PadProps,
  SpringProps,
  TransitionProps,
  SpringValue,
  EasingValue,
  TransitionValue,
  SectionProps,
};

import { useRender } from "@base-ui/react/use-render";
import { mergeProps } from "@base-ui/react/merge-props";
