    );
    --typeset-rule: var(--color-border, color-mix(in oklab, currentColor 20%, transparent));
  }

  .typeset *:not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    /* Paragraphs. */
    &:where(p) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
      text-wrap: pretty;
    }

    /* Headings. */
    &:where(h1, h2, h3, h4, h5, h6) {
      color: var(--color-foreground, currentColor);
      font-family: var(--font-heading);
      font-weight: 600;
      text-wrap: balance;
      margin-block-end: 0;
    }
    &:where(h1) {
      font-size: var(--text-display);
      line-height: var(--text-display--line-height);
      font-weight: var(--text-display--font-weight);
      margin-block-start: 1.5em;
    }
    &:where(h2) {
      font-size: var(--text-title);
      line-height: var(--text-title--line-height);
      font-weight: var(--text-title--font-weight);
      margin-block-start: calc(1.5em * 1.4);
    }
    &:where(h3) {
      font-size: var(--text-subtitle);
      line-height: var(--text-subtitle--line-height);
      font-weight: var(--text-subtitle--font-weight);
      margin-block-start: 1.5em;
    }
    &:where(h4, h5, h6) {
      font-size: 1em;
      line-height: var(--text-body--line-height);
      margin-block-start: 1.5em;
    }
    /* Anchors. */
    &:where([id]) {
      scroll-margin-block-start: 1.5em;
    }

    /* Headings own the space below them. */
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }

    /* Links. */
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-line: underline;
      text-decoration-thickness: from-font;
      text-underline-position: from-font;
      text-underline-offset: 0.2em;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
    }
    &:where(a:hover) {
      text-decoration-color: currentColor;
    }
    &:where(a:focus-visible) {
      outline: 2px solid var(--color-ring, currentColor);
      outline-offset: 2px;
      border-radius: 0.125em;
    }
    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }

    /* Inline semantics. */
    &:where(strong, b) {
      font-weight: 600;
    }
    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }
    &:where(mark) {
      background-color: var(
        --color-warning-soft,
        color-mix(in oklab, currentColor 12%, transparent)
      );
      color: inherit;
      padding: 0.05em 0.15em;
      border-radius: 0.2em;
    }
    &:where(abbr[title]) {
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
      cursor: help;
    }
    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }
    &:where(sup, sub) {
      font-size: 0.75em;
      line-height: 0;
      position: relative;
      vertical-align: baseline;
    }
    &:where(sup) {
      top: -0.5em;
    }
    &:where(sub) {
      bottom: -0.25em;
    }
    &:where(sup a) {
      text-decoration-line: none;
      font-weight: 500;
    }

    /* Lists. */
    &:where(ul) {
      list-style-type: disc;
    }
    &:where(ol) {
      list-style-type: decimal;
    }
    &:where(ul ul) {
      list-style-type: circle;
    }
    &:where(ul ul ul) {
      list-style-type: square;
    }
    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }
    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }
    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }
    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }
    &:where(ul, ol) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
      padding-inline-start: 1.5em;
    }
    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }
    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }
    &:where(ul > li)::marker {
      color: var(--typeset-muted);
    }
    &:where(ol > li)::marker {
      color: var(--typeset-muted);
    }

    /* GFM task lists. */
    &:where(ul.contains-task-list) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }
    &:where(li.task-list-item > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
      accent-color: var(--color-selection, currentColor);
    }

    /* Disclosures. */
    &:where(details) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
    }
    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }
    &:where(summary)::marker {
      color: var(--typeset-muted);
    }

    /* Keyboard keys. */
    &:where(kbd) {
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
      border: 1px solid var(--typeset-rule);
      border-block-end-width: 2px;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
    }

    /* Definition lists. */
    &:where(dl) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
    }
    &:where(dt) {
      font-weight: 500;
      margin-block-start: 1em;
    }
    &:where(dt + dt) {
      margin-block-start: 0.25em;
    }
    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--typeset-muted);
    }

    /* Inline code. */
    &:where(:not(pre) > code) {
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));
      @apply text-inline-code;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.125em 0.3em;
    }

    /* Code blocks. */
    &:where(pre) {
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));
      font-family: var(--font-mono);
      @apply text-code-block;
      tab-size: 2;
      direction: ltr;
      border-radius: var(--radius, 0.5em);
      padding: 0.75em 1em;
      overflow-x: auto;
      margin-block-start: 1.5em;
      margin-block-end: 0;
    }
    &:where(pre code) {
      background-color: transparent;
      font-family: inherit;
      font-size: inherit;
      padding: 0;
      border-radius: 0;
    }

    /* Blockquote. */
    &:where(blockquote) {
      border-inline-start: 2px solid var(--typeset-rule);
      padding-inline-start: 1em;
      margin-block-start: 1.5em;
      margin-block-end: 0;
      margin-inline: 0;
    }

    /* Dividers. */
    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
      margin-block-start: calc(1.5em * 2.4);
      margin-block-end: 0;
    }
    &:where(hr + h1, hr + h2, hr + h3, hr + h4) {
      margin-block-start: 1.5em;
    }

    /* GFM footnotes. */
    &:where(.footnotes, [data-footnotes]) {
      margin-block-start: calc(1.5em * 2);
      border-block-start: 1px solid var(--typeset-rule);
      padding-block-start: 1.5em;
      font-size: 0.875em;
      color: var(--typeset-muted);
    }

    /* Math. */
    &:where(math[display="block"]) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
      overflow-x: auto;
      overflow-y: hidden;
      padding-block: 0.25em;
    }

    /* Media. */
    &:where(img, video) {
      border-radius: var(--radius, 0.5em);
      max-width: 100%;
      height: auto;
      margin-block-start: 1.5em;
      margin-block-end: 0;
    }
    &:where(p img) {
      margin-block-start: 0;
    }
    &:where(figure) {
      margin-block-start: 1.5em;
      margin-block-end: 0;
      margin-inline: 0;
    }
    &:where(figcaption, caption) {
      color: var(--typeset-muted);
      font-size: 0.875em;
      text-align: center;
      margin-block-start: calc(0.75em / 0.875);
    }
    &:where(caption) {
      caption-side: bottom;
    }

    /* Tables. Separators sit on cells, not tr:last-child: append-safe.
       Bare tables stay real tables (keep their semantics) and wrap to fit. */
    &:where(table) {
      max-width: 100%;
      font-size: 1em;
      line-height: 1.5;
      font-variant-numeric: tabular-nums;
      border-collapse: separate;
      border-spacing: 0;
      border-block-end: 1px solid var(--typeset-rule);
      margin-block-start: 1.5em;
      margin-block-end: 0;
    }

    /* Horizontal scroll for any wide block. Wrap it and the wrapper owns the
       flow margin. Tables shrink to fit, so widen the table to make it scroll
       instead of compress. */
    &:where(.typeset-scroll) {
      overflow-x: auto;
      margin-block-start: 1.5em;
    }
    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }
    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }
    &:where(thead th) {
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
      padding: 0.65em 1em;
    }
    &:where(:is(tbody, tfoot) :is(td, th)) {
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
      border-block-start: 1px solid var(--typeset-rule);
    }
    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }
    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }
    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }
    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    /* Blocks inside list items keep the list's tighter rhythm. */
    &:where(li > blockquote, li > table, li > figure) {
      margin-block-start: 0.5em;
    }
    &:where(li > pre) {
      margin-block-start: calc(0.5em / 0.875);
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }
      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    /* Forced colors strips the code background, so give it a border. */
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  /* First child adds no space above. Last so it wins ties. */
  .typeset
    > :where(:first-child):not(
      :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
    ),
  .typeset
    > :where(:first-child)
    > :where(:first-child):not(
      :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    margin-block-start: 0;
  }
}

/* Shared roles for interfaces and reading content. Sizes respect browser zoom. */
@theme static {
  --text-display: 2rem;
  --text-display--line-height: 1.25;
  --text-display--font-weight: 700;
  --text-title: 1.5rem;
  --text-title--line-height: 1.333333;
  --text-title--font-weight: 600;
  --text-subtitle: 1.125rem;
  --text-subtitle--line-height: 1.444444;
  --text-subtitle--font-weight: 600;
  --text-body: 1rem;
  --text-body--line-height: 1.625;
  --text-body--font-weight: 400;
  --text-caption: 0.875rem;
  --text-caption--line-height: 1.571429;
  --text-caption--font-weight: 400;
  /* Density roles: controls and supporting text are not article paragraphs. */
  --text-control: 0.875rem;
  --text-control--line-height: 1.428571;
  --text-control--font-weight: 500;
  --text-control-sm: 0.75rem;
  --text-control-sm--line-height: 1.5;
  --text-control-sm--font-weight: 500;
}

@utility text-display {
  font-family: var(--font-heading);
  text-wrap: balance;
}

@utility text-title {
  font-family: var(--font-heading);
  text-wrap: balance;
}

@utility text-subtitle {
  font-family: var(--font-heading);
  text-wrap: balance;
}

@utility text-body {
  text-wrap: pretty;
}

@utility text-caption {
  text-wrap: pretty;
}

/* Arabic-script marks need more vertical room. Keep natural tracking. */
@layer base {
  :where(:lang(ar), :lang(fa), :lang(ur)) {
    --text-display--line-height: 1.5;
    --text-title--line-height: 1.5;
    --text-subtitle--line-height: 1.6;
    --text-body--line-height: 1.75;
    --text-caption--line-height: 1.75;
    --text-control--line-height: 1.6;
    --text-control-sm--line-height: 1.6;
  }
}

@layer base {
  :where(code, pre) {
    font-variant-ligatures: none;
  }
}

/* Supporting roles reuse the scale; they do not expose another size ladder. */
@utility text-metadata {
  font-size: var(--text-control-sm);
  line-height: var(--text-control-sm--line-height);
  font-weight: 400;
}

@utility text-code-block {
  font-size: var(--text-caption);
  line-height: 1.6;
  font-weight: 400;
  font-family: var(--font-mono);
  font-variant-ligatures: none;
}

@utility text-inline-code {
  font-size: 0.875em;
  line-height: inherit;
  font-weight: 400;
  font-family: var(--font-mono);
  font-variant-ligatures: none;
  overflow-wrap: anywhere;
}

/* Editable text follows its preview rather than establishing another scale. */
@utility text-editable {
  font: inherit;
  letter-spacing: inherit;
}

/* Touch inputs stay at 16px, even on tablets with a wide viewport. */
@utility text-field {
  font-size: var(--text-body);
  line-height: var(--text-body--line-height);
  font-weight: 400;

  @media (min-width: 48rem) and (pointer: fine) {
    font-size: var(--text-control);
    line-height: var(--text-control--line-height);
  }
}

/*
 * Erbium-only variants and tokens. The shared data-* state variants, accordion
 * keyframes, scroll-fade, shimmer and no-scrollbar utilities come from
 * `shadcn/tailwind.css`, imported in globals.css.
 */

@theme inline {
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
}

/* Persistent control engagement, independent of the primitive's state API. */
@custom-variant engaged {
  &:where(
    [aria-expanded="true"],
    [aria-pressed="true"],
    [data-state="on"],
    [data-popup-open]:not([data-popup-open="false"])
  ) {
    @slot;
  }
}

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import type * as React from "react";
import { switchGeometryClassName } from "@/registry/erbium/lib/switch-styles";
import { cn } from "@/registry/erbium/lib/erbium-utils";

const switchIconClassName =
  "pointer-events-none absolute inset-y-0 grid w-[calc(100%-var(--switch-thumb))] place-content-center transition-[scale,opacity] duration-200 ease-out motion-reduce:transition-none [&_svg]:size-2.25 group-data-[size=sm]/switch:[&_svg]:size-1.75";

function Switch({
  className,
  size = "default",
  startIcon,
  endIcon,
  thumbIcon,
  ...props
}: SwitchPrimitive.Root.Props & {
  size?: "sm" | "default";
  /** Shown on the track's start side while the switch is on. */
  startIcon?: React.ReactNode;
  /** Shown on the track's end side while the switch is off. */
  endIcon?: React.ReactNode;
  /** Shown on the thumb in both states. */
  thumbIcon?: React.ReactNode;
}) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      data-size={size}
      className={cn(
        "peer group/switch @container relative inline-flex shrink-0 items-center rounded-full border px-px border-transparent transition-all outline-none group-has-focus-visible/field-card:not-aria-invalid:border-transparent group-has-focus-visible/field-card:not-aria-invalid:ring-0 after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring not-data-disabled:not-data-readonly:active:[--switch-thumb-stretch:1.2] aria-invalid:border-error aria-invalid:ring-[1.5px] aria-invalid:ring-invalid-halo aria-invalid:focus-visible:border-error  motion-reduce:transition-none dark:aria-invalid:border-invalid dark:aria-invalid:focus-visible:border-invalid data-checked:bg-selection data-unchecked:bg-input dark:data-unchecked:bg-input/80 data-disabled:cursor-not-allowed data-disabled:opacity-50",
        switchGeometryClassName,
        className,
      )}
      {...props}
    >
      {startIcon ? (
        <span
          aria-hidden
          data-slot="switch-start-icon"
          className={cn(
            switchIconClassName,
            "inset-s-0 scale-0 text-selection-foreground opacity-0 group-data-checked/switch:scale-100 group-data-checked/switch:opacity-100",
          )}
        >
          {startIcon}
        </span>
      ) : null}
      {endIcon ? (
        <span
          aria-hidden
          data-slot="switch-end-icon"
          className={cn(
            switchIconClassName,
            "inset-e-0 scale-0 text-muted-foreground opacity-0 group-data-unchecked/switch:scale-100 group-data-unchecked/switch:opacity-100",
          )}
        >
          {endIcon}
        </span>
      ) : null}
      {/* The thumb springs across the track and stretches toward the
          center while pressed; 100cqw is the track's inner width. */}
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className="pointer-events-none relative z-10 block h-(--switch-thumb) w-[calc(var(--switch-thumb)*var(--switch-thumb-stretch,1))] rounded-full bg-background ring-0 transition-[translate,width,background-color] duration-200 ease-[cubic-bezier(0.34,1.56,0.64,1)] motion-reduce:transition-none data-checked:translate-x-[calc(100cqw-100%)] rtl:data-checked:-translate-x-[calc(100cqw-100%)] dark:data-checked:bg-selection-foreground dark:data-unchecked:bg-foreground"
      >
        {thumbIcon ? (
          <span
            aria-hidden
            data-slot="switch-thumb-icon"
            className="absolute inset-0 grid place-content-center text-muted-foreground [&_svg]:size-2.25 group-data-[size=sm]/switch:[&_svg]:size-1.75"
          >
            {thumbIcon}
          </span>
        ) : null}
      </SwitchPrimitive.Thumb>
    </SwitchPrimitive.Root>
  );
}

export { Switch };

