      name={props.name}
      render={(defaultProps: React.ComponentProps<"textarea">) => (
        <textarea
          data-slot="textarea"
          className={cn(textareaClassName, className)}
          {...mergeProps(defaultProps, props)}
        />
      )}
    />
  );
}

